import { Navigate } from 'react-router-dom';

const ProtectedRoute = ({ children, isAuthenticated = false, requiredRole = null, userRole = null }) => {
  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }

  // Si un rôle spécifique est requis et que l'utilisateur ne l'a pas,
  // rediriger vers la page d'accueil (ou une page publique) plutôt
  // que vers le dashboard.
  if (requiredRole && userRole !== requiredRole) {
    return <Navigate to="/" replace />;
  }

  return children;
};

export default ProtectedRoute;
